<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { InspectorModelInfo, InspectorValue } from '../../../src/index'
import InspectorModel from './InspectorModel.vue'
import { ICON_CODES } from '../../actions/uiactiondata'
import { qtrc } from '../../i18n'
import { currentScore } from '../../scoreview'
import { inspectorPropertyChanges, inspectorPropertyResets } from '../../../src/index'
import InspectorSpin from './InspectorSpin.vue'
import { applyInspectorChanges, scoreChanged } from '../editbridge'

const props = defineProps<{ model: InspectorModelInfo }>()
const properties = computed(() => props.model.properties)
const styleValue = computed(() => Number(properties.value.fontStyle?.value ?? 0))
const font = ref('')
watch(() => properties.value.fontFamily?.value, value => { font.value = typeof value === 'string' ? value : '' }, { immediate: true })
function radioKeydown(event: KeyboardEvent) {
  const direction = ['ArrowRight', 'ArrowDown'].includes(event.key) ? 1 : ['ArrowLeft', 'ArrowUp'].includes(event.key) ? -1 : 0
  if (!direction) return
  const buttons = [...(event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role="radio"]')]
  const current = buttons.indexOf(document.activeElement as HTMLButtonElement)
  if (current < 0 || !buttons.length) return
  event.preventDefault()
  buttons[(current + direction + buttons.length) % buttons.length]?.focus()
}
function change(property: string, value: InspectorValue) {
  const score = currentScore()
  if (!score) return
  const changes = inspectorPropertyChanges(score, { section: 'SECTION_TEXT', path: [], property }, value)
  if (applyInspectorChanges(score, changes)) scoreChanged()
}
function reset(property: string) {
  const score = currentScore()
  if (score && applyInspectorChanges(score, inspectorPropertyResets(score, { section: 'SECTION_TEXT', path: [], property }))) scoreChanged()
}
const expanded = ref(false)
const textStyles = computed(() => (props.model.flags.textStyles ?? []) as { value: number; text: string }[])
function commitFont() { if (font.value && font.value !== properties.value.fontFamily?.value) change('fontFamily', font.value) }
function glyph(name: string) { const code = ICON_CODES[name]; return code ? String.fromCodePoint(code) : '' }
function color(value: InspectorValue | null): string {
  if (typeof value !== 'string') return '#000000'
  return value.length === 9 && value.startsWith('#') ? `#${value.slice(3)}` : value || '#000000'
}
const fontStyles = [
  { bit: 1, icon: 'TEXT_BOLD', title: qtrc('inspector', 'Bold') }, { bit: 2, icon: 'TEXT_ITALIC', title: qtrc('inspector', 'Italic') },
  { bit: 4, icon: 'TEXT_UNDERLINE', title: qtrc('inspector', 'Underline') }, { bit: 8, icon: 'TEXT_STRIKE', title: qtrc('inspector', 'Strikethrough') },
]
</script>
<template>
  <div class="insp-column">
    <div class="insp-property"><div class="insp-property-title"><label for="text-font">{{ qtrc('inspector', 'Font') }}</label><button class="insp-reset" :disabled="!properties.fontFamily?.isModified || !properties.fontFamily?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('fontFamily')">{{ glyph('UNDO') }}</button></div><input id="text-font" v-model="font" type="text" class="insp-text" :placeholder="properties.fontFamily?.isUndefined ? '--' : ''" :disabled="!properties.fontFamily?.isEnabled" @blur="commitFont" @keydown.enter="commitFont" /></div>
    <div class="insp-row"><div class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Style') }}</span><button class="insp-reset" :disabled="!properties.fontStyle?.isModified || !properties.fontStyle?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('fontStyle')">{{ glyph('UNDO') }}</button></div><div class="insp-radio-group" role="group" :aria-label="qtrc('inspector', 'Style')"><button v-for="item in fontStyles" :key="item.bit" class="insp-radio insp-icon" :aria-pressed="!!(styleValue & item.bit)" :aria-label="item.title" :title="item.title" :disabled="!properties.fontStyle?.isEnabled" @click="change('fontStyle', styleValue ^ item.bit)">{{ glyph(item.icon) }}</button></div></div><div class="insp-property"><div class="insp-property-title"><label for="text-size">{{ qtrc('inspector', 'Size') }}</label><button class="insp-reset" :disabled="!properties.fontSize?.isModified || !properties.fontSize?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('fontSize')">{{ glyph('UNDO') }}</button></div><InspectorSpin id="text-size" :label="qtrc('inspector', 'Size')" :value="properties.fontSize?.value as number | null" :min="1" :max="99" :step="1" :unit="qtrc('global', 'pt')" :disabled="!properties.fontSize?.isEnabled" @commit="v => change('fontSize', v)" /></div></div>
    <div v-if="properties.horizontalAlignment?.isVisible" class="insp-property">
      <div class="insp-property-title"><span>{{ qtrc('inspector', 'Alignment') }}</span><button class="insp-reset" :disabled="!properties.horizontalAlignment.isModified || !properties.horizontalAlignment.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('horizontalAlignment')">{{ glyph('UNDO') }}</button></div><div class="insp-row">
      <div v-if="model.flags.isHorizontalAlignmentAvailable !== false" class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', 'Horizontal alignment')" @keydown="radioKeydown">
        <button v-for="item in [{ v: 0, icon: 'TEXT_ALIGN_LEFT', t: 'Align left' }, { v: 2, icon: 'TEXT_ALIGN_CENTER', t: 'Align center' }, { v: 1, icon: 'TEXT_ALIGN_RIGHT', t: 'Align right' }, { v: 3, icon: 'TEXT_ALIGN_JUSTIFY', t: 'Align justify' }]" :key="item.v" class="insp-radio insp-icon" role="radio" :aria-checked="properties.horizontalAlignment.value === item.v" :tabindex="properties.horizontalAlignment.value === item.v || (properties.horizontalAlignment.isUndefined && item.v === 0) ? 0 : -1" :aria-label="qtrc('inspector', item.t)" :disabled="!properties.horizontalAlignment.isEnabled" @click="change('horizontalAlignment', item.v)">{{ glyph(item.icon) }}</button>
      </div>
      <div v-if="properties.horizontalPosition?.isVisible && model.flags.isPositionAvailable !== false" class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', 'Position')" @keydown="radioKeydown">
        <button v-for="item in [{ v: 0, icon: model.flags.usePositionRelativeToLine ? 'ALIGN_LEFT' : 'NOTE_ALIGN_LEFT', t: model.flags.leftPositionText }, { v: 2, icon: model.flags.usePositionRelativeToLine ? 'ALIGN_HORIZONTAL_CENTER' : 'NOTE_ALIGN_CENTER', t: model.flags.centerPositionText }, { v: 1, icon: model.flags.usePositionRelativeToLine ? 'ALIGN_RIGHT' : 'NOTE_ALIGN_RIGHT', t: model.flags.rightPositionText }]" :key="item.v" class="insp-radio insp-icon" role="radio" :aria-checked="properties.horizontalPosition.value === item.v" :tabindex="properties.horizontalPosition.value === item.v || (properties.horizontalPosition.isUndefined && item.v === 0) ? 0 : -1" :aria-label="String(item.t ?? '')" :disabled="!properties.horizontalPosition.isEnabled" @click="change('horizontalPosition', item.v)">{{ glyph(item.icon) }}</button>
      </div>
      </div><div v-if="properties.verticalAlignment?.isVisible" class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', 'Vertical alignment')" @keydown="radioKeydown">
        <button v-for="item in [{ v: 0, icon: 'TEXT_ALIGN_TOP', t: 'Align top' }, { v: 1, icon: 'TEXT_ALIGN_MIDDLE', t: 'Align middle' }, { v: 2, icon: 'TEXT_ALIGN_BOTTOM', t: 'Align bottom' }, { v: 3, icon: 'TEXT_ALIGN_BASELINE', t: 'Align baseline' }]" :key="item.v" class="insp-radio insp-icon" role="radio" :aria-checked="properties.verticalAlignment.value === item.v" :tabindex="properties.verticalAlignment.value === item.v || (properties.verticalAlignment.isUndefined && item.v === 0) ? 0 : -1" :aria-label="qtrc('inspector', item.t)" :disabled="!properties.verticalAlignment.isEnabled" @click="change('verticalAlignment', item.v)">{{ glyph(item.icon) }}</button>
      </div>
    </div>
    <template v-if="!model.isEmpty">
      <div class="insp-showmore"><button class="insp-expand" :aria-expanded="expanded" @click="expanded = !expanded"><span class="insp-arrow" aria-hidden="true">{{ glyph('SMALL_ARROW_DOWN') }}</span>{{ qtrc('inspector', expanded ? 'Show less' : 'Show more') }}</button>
        <div v-if="expanded" class="insp-column">
          <div class="insp-row"><div class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', model.flags.isSymbolSizeAvailable ? 'Symbol size' : 'Scale') }}</span><button class="insp-reset" :disabled="!properties[model.flags.isSymbolSizeAvailable ? 'symbolSize' : 'symbolScale']?.isModified || !properties[model.flags.isSymbolSizeAvailable ? 'symbolSize' : 'symbolScale']?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset(model.flags.isSymbolSizeAvailable ? 'symbolSize' : 'symbolScale')">{{ glyph('UNDO') }}</button></div><InspectorSpin :label="qtrc('inspector', model.flags.isSymbolSizeAvailable ? 'Symbol size' : 'Scale')" :value="properties[model.flags.isSymbolSizeAvailable ? 'symbolSize' : 'symbolScale']?.value as number | null" :min="1" :max="model.flags.isSymbolSizeAvailable ? 99 : 1000" :step="model.flags.isSymbolSizeAvailable ? 0.5 : 1" :unit="model.flags.isSymbolSizeAvailable ? qtrc('global', 'pt') : '%'" :disabled="!properties[model.flags.isSymbolSizeAvailable ? 'symbolSize' : 'symbolScale']?.isEnabled" @commit="v => change(model.flags.isSymbolSizeAvailable ? 'symbolSize' : 'symbolScale', v)" /></div><div class="insp-property" /></div>
          <label v-if="properties.isSizeSpatiumDependent?.isVisible" class="insp-checkbox"><input type="checkbox" :checked="properties.isSizeSpatiumDependent.value === true" :disabled="!properties.isSizeSpatiumDependent.isEnabled" @change="change('isSizeSpatiumDependent', ($event.target as HTMLInputElement).checked)" />{{ qtrc('inspector', 'Scale with staff size') }}</label>
          <div v-if="model.flags.isScriptSizeAvailable !== false && properties.textScriptAlignment?.isVisible" class="insp-property" :class="{ disabled: !properties.textScriptAlignment.isEnabled }"><div class="insp-row insp-untitled"><div class="insp-radio-group" role="radiogroup" @keydown="radioKeydown"><button v-for="item in [{ value: 2, icon: 'TEXT_SUBSCRIPT', title: 'Subscript' }, { value: 1, icon: 'TEXT_SUPERSCRIPT', title: 'Superscript' }]" :key="item.value" class="insp-radio insp-icon" role="radio" :aria-checked="properties.textScriptAlignment.value === item.value" :tabindex="properties.textScriptAlignment.value === item.value || (properties.textScriptAlignment.isUndefined && item.value === 2) ? 0 : -1" :aria-label="qtrc('inspector', item.title)" :disabled="!properties.textScriptAlignment.isEnabled" @click="change('textScriptAlignment', item.value)">{{ glyph(item.icon) }}</button></div><button class="insp-reset" :disabled="!properties.textScriptAlignment.isModified || !properties.textScriptAlignment.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('textScriptAlignment')">{{ glyph('UNDO') }}</button></div></div>
          <template v-if="!model.flags.isDynamicSpecificSettings && properties.frameType?.isVisible">
            <div class="insp-property" :class="{ disabled: !properties.frameType.isEnabled }"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Frame') }}</span><button class="insp-reset" :disabled="!properties.frameType.isModified || !properties.frameType.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('frameType')">{{ glyph('UNDO') }}</button></div><div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', 'Frame')" @keydown="radioKeydown"><button v-for="item in [{ value: 0, title: qtrc('inspector', 'None', 'text frame type'), icon: '' }, { value: 1, title: qtrc('inspector', 'Rectangle', 'text frame type'), icon: 'FRAME_SQUARE' }, { value: 2, title: qtrc('inspector', 'Circle', 'text frame type'), icon: 'FRAME_CIRCLE' }]" :key="item.value" class="insp-radio" :class="{ 'insp-icon': item.icon }" :aria-label="item.title" role="radio" :aria-checked="properties.frameType.value === item.value" :tabindex="properties.frameType.value === item.value || (properties.frameType.isUndefined && item.value === 0) ? 0 : -1" :disabled="!properties.frameType.isEnabled" @click="change('frameType', item.value)">{{ item.icon ? glyph(item.icon) : item.title }}</button></div></div>
            <template v-if="properties.frameType.value !== 0">
              <div class="insp-row"><div v-for="item in [{key:'frameBorderColor',title:'Border color'}, {key:'frameFillColor',title:'Fill color'}]" :key="item.key" class="insp-property" :class="{ disabled: !properties[item.key]?.isEnabled }"><div class="insp-property-title"><span>{{ qtrc('inspector', item.title) }}</span><button class="insp-reset" :disabled="!properties[item.key]?.isModified || !properties[item.key]?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset(item.key)">{{ glyph('UNDO') }}</button></div><input class="insp-color" type="color" :aria-label="qtrc('inspector', item.title)" :value="color(properties[item.key]?.value ?? null)" :disabled="!properties[item.key]?.isEnabled" @change="change(item.key, typeof properties[item.key]?.value === 'string' && (properties[item.key].value as string).length === 9 ? `#${(properties[item.key].value as string).slice(1, 3)}${($event.target as HTMLInputElement).value.slice(1)}` : ($event.target as HTMLInputElement).value)" /></div></div>
              <div class="insp-row"><div v-for="item in [{key:'frameThickness',title:'Thickness',min:0.1}, {key:'frameMargin',title:'Padding',min:0}]" :key="item.key" class="insp-property" :class="{ disabled: !properties[item.key]?.isEnabled }"><div class="insp-property-title"><span>{{ qtrc('inspector', item.title) }}</span><button class="insp-reset" :disabled="!properties[item.key]?.isModified || !properties[item.key]?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset(item.key)">{{ glyph('UNDO') }}</button></div><InspectorSpin :label="qtrc('inspector', item.title)" :value="properties[item.key]?.value as number | null" :min="item.min" :max="5" :step="0.1" :unit="qtrc('global', 'sp')" :disabled="!properties[item.key]?.isEnabled" @commit="v => change(item.key, v)" /></div></div>
              <div class="insp-property" :class="{ disabled: !properties.frameCornerRadius?.isEnabled }"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Corner radius') }}</span><button class="insp-reset" :disabled="!properties.frameCornerRadius?.isModified || !properties.frameCornerRadius?.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('frameCornerRadius')">{{ glyph('UNDO') }}</button></div><InspectorSpin :label="qtrc('inspector', 'Corner radius')" :value="properties.frameCornerRadius?.value as number | null" :min="0" :max="100" :step="1" :unit="qtrc('global', 'sp')" :disabled="!properties.frameCornerRadius?.isEnabled" @commit="v => change('frameCornerRadius', v)" /></div>
            </template>
          </template>
          <template v-if="model.flags.isLineSpacingAvailable !== false && properties.textLineSpacing?.isVisible"><div class="insp-separator" role="separator" /><div class="insp-row"><div class="insp-property" :class="{ disabled: !properties.textLineSpacing.isEnabled }"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Line spacing') }}</span><button class="insp-reset" :disabled="!properties.textLineSpacing.isModified || !properties.textLineSpacing.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('textLineSpacing')">{{ glyph('UNDO') }}</button></div><InspectorSpin :label="qtrc('inspector', 'Line spacing')" :value="properties.textLineSpacing.value as number | null" :min="0" :max="10" :step="0.1" :decimals="2" :unit="qtrc('global', 'li')" :disabled="!properties.textLineSpacing.isEnabled" @commit="v => change('textLineSpacing', v)" /></div><div class="insp-property" /></div></template>
          <template v-if="!model.flags.isDynamicSpecificSettings">
            <div class="insp-separator" role="separator" />
            <div v-if="properties.textType?.isVisible" class="insp-property" :class="{ disabled: !properties.textType.isEnabled }"><div class="insp-property-title"><label for="text-type">{{ qtrc('inspector', 'Text style') }}</label><button class="insp-reset" :disabled="!properties.textType.isModified || !properties.textType.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('textType')">{{ glyph('UNDO') }}</button></div><select id="text-type" class="insp-dropdown" :value="properties.textType.isUndefined || !textStyles.some(o => o.value === properties.textType.value) ? '' : String(properties.textType.value)" :disabled="!properties.textType.isEnabled" @change="change('textType', Number(($event.target as HTMLSelectElement).value))"><option v-if="properties.textType.isUndefined || !textStyles.some(o => o.value === properties.textType.value)" value="">--</option><option v-for="option in textStyles" :key="option.value" :value="option.value">{{ option.text }}</option></select></div>
            <div v-if="properties.textPlacement?.isVisible && model.flags.isPositionAvailable !== false" class="insp-property"><div class="insp-property-title"><span>{{ qtrc('inspector', 'Position') }}</span><button class="insp-reset" :disabled="!properties.textPlacement.isModified || !properties.textPlacement.isEnabled" :aria-label="qtrc('inspector', 'Reset property to default value')" @click="reset('textPlacement')">{{ glyph('UNDO') }}</button></div><div class="insp-radio-group" role="radiogroup" :aria-label="qtrc('inspector', 'Position')" @keydown="radioKeydown"><button v-for="item in properties.textPlacement.options ?? []" :key="String(item.value)" class="insp-radio" role="radio" :aria-checked="properties.textPlacement.value === item.value" :tabindex="properties.textPlacement.value === item.value || (properties.textPlacement.isUndefined && item === properties.textPlacement.options?.[0]) ? 0 : -1" :disabled="!properties.textPlacement.isEnabled" @click="change('textPlacement', item.value)">{{ item.text }}</button></div></div>
          </template>
          <button v-if="model.flags.areStaffTextPropertiesAvailable" class="insp-flat-button" disabled>{{ qtrc('inspector', 'Staff text properties') }}</button>
        </div>
      </div>
    </template>
  </div>
</template>
